let palette;
let size;
let expand;
let diagramInstance;
let paletteIconInstance;
let paletteSpaceInstance;
let scrollableArea = new Rect(0, 0, 1500, 1500);
let isItemText = false;
let symbolSize = 50;
let htmlSymbolWidth = 91;
let htmlSymbolHeight = 100;
//Initializes the symbol palette
function SymbolPalette() {
    React.useEffect(() => {
        renderComplete();
    }, []);
    function renderComplete() {
        addEvents();
    }
    let isMobile;
    //Enhances webpage functionality for mobile devices with a click event listener.
    function addEvents() {
        isMobile = window.matchMedia('(max-width:550px)').matches;
        if (isMobile) {
            let paletteIcon = paletteIconInstance;
            if (paletteIcon) {
                paletteIcon.addEventListener('click', openPalette, false);
            }
        }
    }
    // Manages the visibility state of the palette space on the webpage for mobile devices.
    function openPalette() {
        let paletteSpace = paletteSpaceInstance;
        isMobile = window.matchMedia('(max-width:550px)').matches;
        if (isMobile) {
            if (!paletteSpace.classList.contains('sb-mobile-palette-open')) {
                paletteSpace.classList.add('sb-mobile-palette-open');
            }
            else {
                paletteSpace.classList.remove('sb-mobile-palette-open');
            }
        }
    }
    //set Node default value
    function symbolDefaults(symbol) {
        if (symbol.shape.type === 'HTML') {
            symbol.width = htmlSymbolWidth;
            symbol.height = htmlSymbolHeight;
        }
        symbol.style = { strokeWidth: 2, strokeColor: '#757575' };
        return symbol;
    }
    function nodeDefaults(node) {
        if (node.id.includes("BugFix")) {
            node.constraints = NodeConstraints.Default;
            node.tooltip.content = "";
        }
        return node;
    }
    function symbolInfo(symbol) {
        if (symbol.shape.type === 'HTML') {
            return { width: htmlSymbolWidth, height: htmlSymbolHeight, fit: true };
        }
        return { width: symbolSize, height: symbolSize, fit: true };
    }
    //Enable or disable the animation for symbol palette
    function onAnimationChange(args) {
        palette.enableAnimation = args.checked;
    }
    //Add or Remove the search for Symbol palette.
    function handleshowSearch(args) {
        if (args.checked) {
            palette.enableSearch = true;
        }
        else {
            palette.enableSearch = false;
        }
    }
    //Add or Remove the Text for Symbol palette item.
    function onItemTextChange(args) {
        isItemText = args.checked;
        updateGetSymbolInfo();
    }
    function updateGetSymbolInfo() {
        palette.getSymbolInfo = (symbol) => {
            let object = {
                width: (symbol.shape.type === 'HTML')
                    ? htmlSymbolWidth : symbolSize,
                height: (symbol.shape.type === 'HTML')
                    ? isItemText ? htmlSymbolHeight + 20 : htmlSymbolHeight
                    : symbolSize,
                fit: true,
                description: {
                    text: isItemText
                        ? (symbol.id === "BugFix" ? "Bug Fix" : symbol.id)
                        : ''
                }
            };
            return object;
        };
        palette.refresh();
    }
    //Enable or disable the headerIcon for symbol palette headers
    function onHeaderIconChange(args) {
        for (let i = 0; i < palette.palettes.length; i++) {
            if (args.checked) {
                if (i === 0) {
                    palette.palettes[i].iconCss = 'e-diagram-icons1 e-diagram-basic';
                }
                else if (i === 1) {
                    palette.palettes[i].iconCss = 'e-diagram-icons1 e-diagram-flow';
                }
                else if (i === 2) {
                    palette.palettes[i].iconCss = 'e-diagram-icons1 e-diagram-connector';
                }
            }
            else {
                palette.palettes[i].iconCss = '';
            }
        }
    }
    function SVGTemplate() {
        let svgnodes = [
            { id: 'Script', shape: { type: 'Native', scale: 'Stretch', content: getTemplateContent('Script') }, width: 80, height: 80 },
            { id: 'Settings', shape: { type: 'Native', scale: 'Stretch', content: getTemplateContent('Settings') }, width: 80, height: 80 },
            { id: 'Bluetooth', shape: { type: 'Native', scale: 'Stretch', content: getTemplateContent('Bluetooth') }, width: 70, height: 70 },
            { id: 'Wi-Fi', shape: { type: 'Native', scale: 'Stretch', content: getTemplateContent('Wi-Fi') }, width: 70, height: 55 },
        ];
        return svgnodes;
    }
    function HTMLTemplate() {
        let htmlNodes = [
            { id: 'Meeting', shape: { type: 'HTML', content: getTemplateContent('Meeting') }, width: 80, height: 80 },
            { id: 'Message', shape: { type: 'HTML', content: getTemplateContent('Message') }, width: 80, height: 80 },
            { id: 'Weather', shape: { type: 'HTML', content: getTemplateContent('Weather') }, width: 70, height: 55 },
            { id: 'BugFix', shape: { type: 'HTML', content: getTemplateContent('BugFix') }, width: 70, height: 70, tooltip: { content: 'Bug Fix' }, constraints: NodeConstraints.Tooltip },
        ];
        return htmlNodes;
    }
    return (<div>
      <style>{SAMPLE_CSS}</style>
      <div className="control-section">
        <div className="diagram-symbolpalette" style={{ width: '100%' }}>
          <div className="palette-column">
            <div className="sb-mobile-palette-bar">
              <div id="palette-icon" ref={(paletteIcon) => (paletteIconInstance = paletteIcon)} role="button" className="e-ddb-icons1 e-toggle-palette"></div>
            </div>
            {/* Column 1: Palette */}
            <div id="palette-space" ref={(paletteSpace) => (paletteSpaceInstance = paletteSpace)} className="sb-mobile-palette">
            <SymbolPaletteComponent id="symbolpalette" ref={(symbolpal) => (palette = symbolpal)} expandMode={'Multiple'} palettes={[
            {
                id: 'flow',
                expanded: true,
                symbols: flowShapes,
                title: 'Flow Shapes',
                iconCss: 'e-diagram-icons1 e-diagram-flow',
            },
            {
                id: 'basic',
                expanded: true,
                symbols: basicShapes,
                title: 'Basic Shapes',
                iconCss: 'e-diagram-icons1 e-diagram-basic',
            },
            {
                id: 'connectors',
                expanded: true,
                symbols: connectorSymbols,
                title: 'Connectors',
                iconCss: 'e-diagram-icons1 e-diagram-connector',
            },
            {
                id: 'nodeSVG',
                expanded: true,
                symbols: SVGTemplate(),
                title: 'SVG Shapes'
            },
            {
                id: 'nodeHtml',
                expanded: true,
                symbols: HTMLTemplate(),
                title: 'HTML Shapes'
            }
        ]} enableAnimation={true} enableSearch={true} width={'100%'} height={'900px'} getNodeDefaults={symbolDefaults.bind(this)} getSymbolInfo={symbolInfo.bind(this)} symbolMargin={{ left: 15, right: 15, top: 15, bottom: 15 }}/>
          </div>
          </div>

          {/* Column 2: Diagram (expands to fill space) */}
          <div className="diagram-column">
            <DiagramComponent id="diagram" ref={(diagram) => (diagramInstance = diagram)} width={'100%'} height={'900px'} rulerSettings={{ showRulers: true }} pageSettings={{ width: 1500, height: 1500 }} getNodeDefaults={nodeDefaults.bind(this)} scrollSettings={{
            scrollLimit: 'Infinity',
            canAutoScroll: true,
            autoScrollBorder: { left: 10, right: 10, top: 10, bottom: 10 },
            scrollableArea: scrollableArea,
        }}></DiagramComponent>
          </div>
          {/* Column 3: Properties */}
          <div className="symbolpalette-property-section">
            <div className="property-panel-section" style={{ paddingLeft: '5px' }}>
              <div className="property-panel-header" style={{ paddingLeft: '0px' }}>Properties</div>
              <div className="property-panel-content">
                <table id="property" title="Properties" style={{ width: '100%', height: '100%' }}>
                  <tbody>
                  <tr style={{ height: "50px" }}>
                    <td>
                      <div>Expandable </div>
                    </td>
                    <td>
                      {/* DropDownList is used to change the expandMode of the Symbolpallete. */}
                      <div style={{ paddingLeft: '20px', paddingTop: '10px' }}>
                        <DropDownListComponent id="expand" index={1} width={120} ref={(expandRef) => (expand = expandRef)} dataSource={expandMode} change={() => {
            palette.expandMode = expand.value;
            palette.dataBind();
        }}/>
                      </div>
                    </td>
                  </tr>
                  <tr style={{ height: "50px" }}>
                    <td>
                      <div>Symbol Size </div>
                    </td>
                    <td>
                      {/* NumericTextBox is used to apply the size of the Symbol. */}
                      <div style={{ paddingLeft: '20px', paddingTop: '10px' }}>
                        <NumericTextBoxComponent id="size" value={50} min={40} max={90} width={120} step={5} format="##.##" change={(args) => {
            if (symbolSize != args.value) {
                symbolSize = args.value;
                updateGetSymbolInfo();
            }
        }} ref={(sizeRef) => (size = sizeRef)}/>
                      </div>
                    </td>
                  </tr>
                  <tr style={{ height: "50px" }}>
                    <td>
                      <div style={{ paddingTop: '14px' }}>Animation </div>
                    </td>
                    <td>
                      {/* Enable or disable the animation of the symbol palette. */}
                      <div style={{ paddingTop: '10px', paddingLeft: '20px' }}>
                        <CheckBoxComponent id="animation" checked={true} change={onAnimationChange}/>
                      </div>
                    </td>
                  </tr>
                  <tr style={{ height: "50px" }}>
                    <td>
                      <div style={{ paddingTop: '14px' }}>Item Text </div>
                    </td>
                    <td>
                      <div style={{ paddingTop: '10px', paddingLeft: '20px' }}>
                        <CheckBoxComponent id="itemtext" change={onItemTextChange}/>
                      </div>
                    </td>
                  </tr>
                  <tr style={{ height: "50px" }}>
                    <td>
                      <div style={{ paddingTop: '14px' }}>Header Icon </div>
                    </td>
                    <td>
                      <div style={{ paddingTop: '10px', paddingLeft: '20px' }}>
                        <CheckBoxComponent id="headericon" checked={true} change={onHeaderIconChange}/>
                      </div>
                    </td>

                  </tr>
                  <tr style={{ height: "50px" }}>
                    <td>
                      <div style={{ paddingTop: '14px' }}>Show Search TextBox </div>
                    </td>
                    <td>
                      <div style={{ paddingTop: '10px', paddingLeft: '20px' }}>
                        <CheckBoxComponent id="showsearch" checked={true} change={handleshowSearch}/>
                      </div>
                    </td>

                  </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>);
}
export default SymbolPalette;

